if (items.length === 0) return [];

// Groupe par (sensor_id, pollutant, hour)
const groups = {};

for (const item of items) {
  const row = item.json;
  const sensorId  = row.sensor_id  || 'unknown';
  const pollutant = row.pollutant   || 'unknown';
  const value     = Number(row.value);
  const ts        = new Date(row.datetime_utc);

  if (Number.isNaN(value) || isNaN(ts.getTime())) continue;

  // Heure arrondie (fenêtre fixe)
  const hour = new Date(ts);
  hour.setUTCMinutes(0, 0, 0);
  const hourKey = hour.toISOString();

  const key = `${sensorId}__${pollutant}__${hourKey}`;

  if (!groups[key]) {
    groups[key] = {
      sensor_id:   sensorId,
      pollutant:   pollutant,
      hour_utc:    hourKey,
      city:        row.city        || null,
      latitude:    row.latitude    != null ? Number(row.latitude)  : null,
      longitude:   row.longitude   != null ? Number(row.longitude) : null,
      sum:         0,
      max:         -Infinity,
      min:         Infinity,
      count:       0,
    };
  }

  const g = groups[key];
  g.sum   += value;
  if (value > g.max) g.max = value;
  if (value < g.min) g.min = value;
  g.count += 1;
}

const out = [];
for (const g of Object.values(groups)) {
  out.push({
    json: {
      sensor_id:     g.sensor_id,
      pollutant:     g.pollutant,
      hour_utc:      g.hour_utc,
      city:          g.city,
      latitude:      g.latitude,
      longitude:     g.longitude,
      avg_value:     g.count > 0 ? Math.round((g.sum / g.count) * 100) / 100 : 0,
      max_value:     g.max === -Infinity ? 0 : g.max,
      min_value:     g.min ===  Infinity ? 0 : g.min,
      samples_count: g.count,
    }
  });
}

return out;
